## 주요 설명
1. 스크롤이 끝나면 페이징을 결정하는 `_fetchNewsCardsIfNeeded` 액션이 발생합니다.

```swift
/// NewsCardScrollView.swift
DragGesture()
  .onChanged { value in
    viewStore.send(.dragOnChanged(value.translation))
  }
  .onEnded { _ in
    viewStore.send(._calculateScrollIndex)
    viewStore.send(._fetchNewsCardsIfNeeded(viewStore.currentScrollIndex, viewStore.newsCards.count))
    viewStore.send(.dragOnEnded)
  }
```

2. 메인 코어에서 액션을 캐치합니다.

```swift
/// MainCore.swift
case let .newsCardScroll(._fetchNewsCardsIfNeeded(currentScrollIndex, newsCardsCount)):
  if newsCardsCount - currentScrollIndex > Constant.pagingCriticalPoint { return .none }
  state.cursorPage += 1
  return Effect(value: ._fetchNewsCards(.continuousPaging))
```

3. 서버에서 가져온 뉴스카드를 상태에 따라 분기합니다~!

```swift
/// MainCore.swift
case let ._fetchNewsCards(fetchType):
  return env.newsCardService.getAllNewsCards(
    state.cursorDate,
    state.cursorPage,
    Constant.pagingSize
  )
  .catchToEffect()
  .flatMapLatest { result -> Effect<MainAction, Never> in
    switch result {
      case let .success(newsCards):
        return Effect(value: ._handleNewsCardsResponse(newsCards, fetchType))
          
      case .failure:
        return .none
    }
  }
  .eraseToEffect()
```

만약 빈 배열이 response로 들어오면 페이징이 끝난 것이므로 커서가 가르키는 날짜를 하루 빼고, 커서 위치도 0으로 돌립니다.

```swift
/// MainCore.swift
private func handleNewsCardsResponse(
  _ state: inout MainState,
  source newsCards: [NewsCard],
  fetchType: FetchType
) -> Effect<MainAction, Never> {
  switch fetchType {
  case .initial:
    if newsCards.isEmpty {
      return .none
    }
    if state.newsCardScrollState == nil {
      return Effect(value: ._setNewsCardScrollState(newsCards))
    }
    
  case .continuousPaging:
    if newsCards.isEmpty {
      state.cursorDate = subtractOneDay(from: state.cursorDate)
      state.cursorPage = 0
      return Effect(value: ._fetchNewsCards(.newPaging))
    } else {
      return Effect(value: .newsCardScroll(._concatenateNewsCards(newsCards)))
    }
    
  case .newPaging:
    if !newsCards.isEmpty {
      return Effect(value: .newsCardScroll(._concatenateNewsCards(newsCards)))
    }
  }
  
  return .none
}
```

4. 새로 받아온 뉴스 카드를 추가합니다~!

```swift
/// NewsCardScrollCore.swift
case let ._concatenateNewsCards(newsCards):
  concatenateNewsCards(&state, source: newsCards)
  return .none


private func concatenateNewsCards(
  _ state: inout NewsCardScrollState,
  source newsCards: [NewsCard]
) {
  let offset = state.newsCards.count
  newsCards.enumerated().forEach { index, card in
    state.degrees.append(0)
    state.offsets.append(.zero)
    state.newsCards.append(
      NewsCardState(
        index: offset + index - 1,
        newsCard: card,
        layout: state.layout,
        isFolded: true
      )
    )
  }
}

```

